insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','gap-bun-ssa','Gap-bun-ssa (갑분싸): The Mood Suddenly Went Cold','Short for "the mood suddenly went awkward"','Used when a comment or action suddenly makes a fun mood cold and awkward. People often say it about their own failed joke to laugh it off.','Around 2017, from Korean forum comment jokes, then streaming chats','Use it to laugh off an awkward moment.','Blaming one person for the gap-bun-ssa can hurt.','{"Awkward silence"}'::text[],'[{"text": "Oops, gap-bun-ssa. Sorry.", "situation": "A joke falls flat"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='163245f2-0684-497c-a400-087c8f8dd8ff' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','gaptuktwi','Gap-tuk-twi (갑툭튀): Popping Out of Nowhere','Short for "suddenly popping out"','Used when something appears out of nowhere, including jump scares in horror films and games. Shinhwa''s Shin Hye-sung used it often on a fan board around 2003, and it is said he made it with Kangta and Lee Ji-hoon of the group S, who also made "kkamnol".','Spread from Shinhwa member Shin Hye-sung''s fan board posts around 2003','Use it for surprise appearances or jump scares.',NULL,'{"Jump scare"}'::text[],'[{"text": "Ah! Too much gap-tuk-twi.", "situation": "Watching a horror film"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='17fb266c-9ee8-48d6-8d4b-95363fbd3855' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','god-saeng','God-saeng (갓생): Living Like a God','A busy, productive, well-planned life','"God" plus "saeng" (from "insaeng", life). It means waking early, working out, studying, and living a model life. People say it as a goal or as praise.','Spread through Korean social media and vlog culture in the early 2020s','Use it for goals or praise.',NULL,'{"God life","Productive life"}'::text[],'[{"text": "Up at 6 a.m. every day. Full god-saeng this year.", "situation": "New Year goal"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='c13f4398-f06c-4b6e-9a58-ba46a4b43c6b' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','gukrul','Guk-rul (국룰): The National Rule','The way everyone just does it','Short for "national rule". No one made it official, but everyone follows it. For example: "Chicken with cola is guk-rul."','Used by online gamers in the late 2000s, everyday slang by around 2019','Fine to use anywhere.',NULL,'{"National rule","Unwritten rule"}'::text[],'[{"text": "Rainy day means pajeon and makgeolli. Guk-rul.", "situation": "Picking food on a rainy day"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='2781414f-8782-4108-89b4-d77afb948da1' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','kkamnol','Kkamnol (깜놀): Startled','Short for "kkamjjak nollada" (to be startled)','A quick way to say you got startled: "kkamnol haetjana!" (you scared me!). A jump scare in a horror film is a "kkamnol scene". It is said to have been coined by members of the group S (Shin Hye-sung, Lee Ji-hoon, Kangta), who also made "gaptuktwi" (popping out of nowhere).','Said to be coined by members of the group S, spread in the late 2000s','Use it when something surprises you.',NULL,'{Startled,"Jump scare"}'::text[],'[{"text": "Ah, kkamnol!", "situation": "A friend calls from behind"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='73e26a79-97fa-441d-a275-90783434fac5' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','as-long-as-its-not-me','Naman Animyeon Dwae (나만 아니면 돼): As Long as It''s Not Me','What winners shouted after dodging a penalty on "2 Days & 1 Night"','On the KBS show "2 Days & 1 Night", members who escaped the penalty in luck games shouted "As long as it''s not me!" Kang Ho-dong''s exaggerated version became a famous meme image. It first meant celebrating your own luck, but is now also used to mock others'' misfortune.','From luck games on the KBS variety show "2 Days & 1 Night"','Use it when you dodge a penalty in a game.','Using it on someone in real trouble sounds cruel.','{"2 Days and 1 Night",Bokbulbok}'::text[],'[{"text": "Naman animyeon dwae~!", "situation": "Escaping cleaning duty in a draw"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='0a04b4c2-c501-49b0-8b9e-99aebf4dbf45' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','are-you-a-t','Are You a T? (너 T야?)','A joking question for someone who answers feelings with facts','In MBTI, "T" (Thinking) types are said to lead with logic over feelings. When you want comfort but get a fix-it list, you ask "Are you a T?". It is a joke, not a real personality test.','Grew with the MBTI boom in Korea, a daily phrase by around 2023','Use it with close friends.','Variants that sound like swear words are best avoided.','{T?,"MBTI T"}'::text[],'[{"text": "I wanted a hug... are you a T?", "situation": "You vent and get only solutions"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='6caf1ca3-40ca-40aa-abe3-89fb610d0f21' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','mind-your-own-business','Neona Jalhaseyo (너나 잘하세요): Mind Your Own Business','A famous line from "Lady Vengeance": worry about yourself','A cold line said by Geum-ja (Lee Young-ae) in Park Chan-wook''s 2005 film "Sympathy for Lady Vengeance". It caught on as a comeback when someone lectures you. It uses polite "-seyo" while being sharp, which makes it funnier.','From Park Chan-wook''s 2005 film "Sympathy for Lady Vengeance"','Use it as a playful comeback to a friend''s nagging.','It sounds rude to someone giving real advice or to seniors.','{"Mind your own business","Lady Vengeance"}'::text[],'[{"text": "Neona jalhaseyo~", "situation": "A friend judges your diet"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='057e5e6d-30c8-45a2-aa68-023c692a7a8d' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','neomsabyeok','Neomsabyeok (넘사벽): Out of Your League','Short for "an uncrossable fourth-dimension wall"','Used when one side is so far ahead that comparison is pointless. It began inside inequality signs like "A>>>>neomsabyeok>>>>B", with more signs meaning a bigger gap. Now people say "their skill is neomsabyeok".','Spread in 2000s Korean forums; exact start unknown','Use it to praise an overwhelming skill or quality.',NULL,'{"Out of league","Next level"}'::text[],'[{"text": "That skill is neomsabyeok.", "situation": "Watching a pro gamer"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='0f190e64-4bb2-427d-8f8d-e2437091b542' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','you-go-to-hawaii','Niga Gara Hawaii (니가 가라 하와이): You Go to Hawaii','A line from the film "Friend": you go instead','In the 2001 film "Friend", Dong-su (Jang Dong-gun) refuses his old friend Joon-seok''s (Yoo Oh-sung) offer to hide in Hawaii, saying in Busan dialect, "You go. Hawaii." The scene is grim, but the short, punchy line became a hit. Now people say it to push a chore back on someone.','From Kwak Kyung-taek''s 2001 film "Friend"','Use it jokingly when a friend tries to hand you a chore.',NULL,'{"Friend movie"}'::text[],'[{"text": "Not me. Niga gara Hawaii.", "situation": "Avoiding a convenience-store run"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='16fe0d7e-68ae-41e2-907d-e530a362ec4c' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','daengdaengi','Daengdaengi (댕댕이): Doggo','A cute word for a dog','It swaps "meong" in "meongmeongi" (doggy) for the similar-looking letter "daeng". This letter-twisting game is called "yamin jeongeum". It started on forums but is now used on TV, ads and even pet café names.','Late 2010s letter-twisting wordplay on Korean forums, then TV and ads','Use it for any cute dog.',NULL,'{Doggo,Puppy}'::text[],'[{"text": "That daengdaengi is so cute.", "situation": "Seeing a dog on a walk"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='0bb41e66-c130-479b-a09f-d4f50d8bd5e9' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','deokjil','Deokjil (덕질): Fangirling / Fanboying','Diving deep into something you love','From "deokhu" (a Korean take on Japanese "otaku") plus "-jil" (doing). It means following, collecting and supporting what you love, like idols, anime or games. Becoming a fan is "ipdeok", quitting is "taldeok".','From otaku-derived "deokhu" in 2000s fan culture, everyday slang by the 2010s','Use it to talk about your fandom or hobby.',NULL,'{Fangirling,Stanning}'::text[],'[{"text": "I am busy with deokjil for that group lately.", "situation": "Catching up"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='f2e8a025-ad47-4919-9081-21df5fa59f70' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','ttinggok','Ttinggok (띵곡): A Banger','A twisted spelling of "myeonggok" (masterpiece song)','The letter "myeong" (명) is swapped for the look-alike "tting" (띵), meaning a great song. This letter-twisting game is "yamin jeongeum", like "daengdaengi". Great works are "ttingjak", great quotes "ttingeon". Common in music comments and playlist titles.','Late 2010s letter-twisting wordplay on Korean forums','Use it to recommend or praise a song.',NULL,'{Banger,ttingjak}'::text[],'[{"text": "Listen to this, total ttinggok.", "situation": "Recommending a song"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='e1d6ded7-8814-415d-a377-c73da9d1f7ab' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','lucky-vicky','Lucky Vicky (럭키비키)','Calling a bad thing secretly lucky, with a smile','When something goes wrong, you flip it: "Actually this is great, totally Lucky Vicky!" It spread from IVE member Jang Won-young and her famously positive way of talking.','From Jang Won-young''s positive way of talking, popularized by a fan parody post in March 2024','Use it to laugh off small bad luck.','Do not use it when a friend is going through something serious.','{"Lucky Vicky","Wonyoung thinking"}'::text[],'[{"text": "Guess I get a nice walk. Total Lucky Vicky.", "situation": "Missed the bus"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='1a4ab02f-f81c-477b-ab2d-66bf0df8cc27' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','legeno','Legeno (레게노): Legendary, Misspelled','A playful misreading of "LEGEND"','Swapping the final D in "LEGEND" for O gives "LEGENO". It reportedly began when streamer Woowakgood''s wife misread "legend" on a Minecraft build during his stream. It exploded in YouTube comments around 2020, even inspiring a fried chicken menu, before fading by mid-2020.','From a misreading on streamer Woowakgood''s Minecraft stream, spread via YouTube comments','Use it in comments for amazing or hilarious moments.',NULL,'{Legend,LEGENO}'::text[],'[{"text": "This scene is legeno.", "situation": "Commenting on a funny clip"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='12561d8c-5aac-44c7-9303-16ba8633128d' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','malatanghulu','Malatanghulu (마라탕후루)','A catchy kids song about malatang and tanghulu','A song by YouTuber Seo Eve that repeats two snacks trending in Korea at the time: spicy malatang and candied fruit tanghulu. Its easy dance became a huge challenge among Korean elementary school kids.','Released by YouTuber Seo Eve in 2024, spread as a short-form challenge','Use it when talking about kid trends.',NULL,'{"Malatang tanghulu song"}'::text[],'[{"text": "Every kid is singing Malatanghulu now.", "situation": "Your niece sings it nonstop"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='28441bc1-4026-44df-b6a7-5017b2203597' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','mukbang','Mukbang (먹방): Eating Broadcast','Short for "eating broadcast", videos of people eating','A video or live stream where a host eats while talking with viewers. It began on the Korean streaming site AfreecaTV (now SOOP), became popular in Korea in the early 2010s and spread worldwide from the mid-2010s. "Mukbang" is now in English dictionaries.','Early AfreecaTV streams, popular in Korea in the early 2010s, global from the mid-2010s','Use it when talking about food videos or someone eating with gusto.','Videos that push overeating may not be healthy.','{"Eating show"}'::text[],'[{"text": "I watched a mukbang and now I want tteokbokki.", "situation": "Choosing dinner"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='e7b868ef-1c85-4f45-8592-d49fed4dd0ef' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','double-or-nothing','Mutgo Double-ro Ga (묻고 더블로 가): Double It!','A line from the film "Tazza": raise the stakes','In the 2006 film "Tazza: The High Rollers", villain Kwak Cheol-yong (Kim Eung-soo) confidently shouts "Leave it in and double it!" at the card table. Thirteen years later, in late 2019, jokes and impressions reviving the character made the line go viral again.','From the 2006 film "Tazza", viral again in late 2019','Use it to jokingly raise the stakes on a bet or challenge.','Do not use it to encourage real gambling.','{Tazza,"Double or nothing"}'::text[],'[{"text": "Lost? Then mutgo double-ro ga!", "situation": "Losing a friendly bet"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='551b558a-b738-493b-9c5a-2c6aa30f671e' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','have-you-been-eating','Bab-eun Meokgo Danini (밥은 먹고 다니냐): Have You Been Eating?','A famous line from "Memories of Murder" by Song Kang-ho','In Bong Joon-ho''s 2003 film "Memories of Murder", detective Park Doo-man (Song Kang-ho) wearily asks a suspect, "Have you been eating?" The film is based on a real unsolved serial murder case. In Korea, "did you eat?" is also a greeting, so the line mixes concern and despair. People now use it as a playful impression.','From Bong Joon-ho''s 2003 film "Memories of Murder"','Use it as a joking check-in with a friend.','The film is about real murders, so do not use it to joke about victims.','{"Memories of Murder"}'::text[],'[{"text": "Bab-eun meokgo danini? Have you been eating?", "situation": "A busy friend"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='a5bcc0c6-3c75-488d-8364-015af9ca88a9' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','byeoldajul','Byeol-da-jul (별다줄): You Shorten Everything','Short for "you even shorten that?"','A teasing word for the habit of cutting any phrase down to its first syllables, like "jeo-me-chu" (dinner menu recommendation). The joke is that the word itself is an abbreviation. It is a good starting point for understanding Korean internet abbreviations.','Late 2010s, a reaction to heavy abbreviation online that became an abbreviation itself','Use it when a friend uses a strange new abbreviation.',NULL,'{"Shortening everything"}'::text[],'[{"text": "What is that now? Total byeol-da-jul.", "situation": "A friend uses an unknown abbreviation"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='f44acf5d-90c4-4678-9dc0-4ed9f23cedc4' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','bulgeum','Bulgeum (불금): Fire Friday','Short for "burning Friday", a fun Friday night out','Friday night is for going out late and having fun. It spread after Korea adopted the five-day work week in 2004 and was common in the media by 2011. It is like English "TGIF". The opposite feeling is "wolyobyeong" (Monday blues).','Spread after the 2004 five-day work week, common in media from 2011','Use it to make Friday plans.',NULL,'{TGIF,"Burning Friday"}'::text[],'[{"text": "It is bulgeum, what should we do?", "situation": "Before leaving work on Friday"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='81768b43-ed50-4c02-aaaf-17105e013186' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','ppangkku-ttongkku','Ppangkku Ttongkku (빵꾸똥꾸): The Sitcom Insult','A childish insult from the sitcom "High Kick Through the Roof"','In the 2009-2010 MBC sitcom "High Kick Through the Roof", the bratty girl Jung Hae-ri (actor Jin Ji-hee) yells "Ya! Ppangkku ttongkku!" (roughly "you fart-butt!") at people she dislikes. People who grew up with the show still use it jokingly.','From the 2009-2010 MBC sitcom "High Kick Through the Roof"','Use it playfully with close friends or siblings.','It is a childish insult, so avoid it in serious settings.','{"High Kick"}'::text[],'[{"text": "Ya, ppangkku ttongkku! Where is my snack?", "situation": "Your sibling ate your snack"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='a5764d8a-abc6-4cd6-9ff1-6052bf3f096e' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','pikki-pikki-challenge','Pikki Pikki Challenge (삐끼삐끼)','A baseball cheer dance that went viral worldwide','KIA Tigers cheerleaders do this short thumbs-up dance when their pitcher strikes out a batter. The cheer started in 2022. A June 2024 clip of cheerleader Lee Ju-eun dancing with a deadpan face spread on TikTok and Instagram and became a global challenge.','KIA Tigers cheer since 2022, viral worldwide from a June 2024 clip','Use it with the dance when something good happens.','Respect the portrait rights of real people in clips.','{"Pikki Pikki","Strikeout dance"}'::text[],'[{"text": "Strike out! Pikki pikki time.", "situation": "A friend loses a bet"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='5a70b638-0aa4-4135-a57f-c57918a535cf' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','sa-ba-sa','Sa-ba-sa (사바사): Depends on the Person','Short for "person by person"','From "ke-ba-ke" (case by case), it means it depends on the person. The pattern spreads: "hoe-ba-hoe" for company by company, "jeom-ba-jeom" for branch by branch. Some people do not know it, so say it plainly with strangers.','From the English "case by case", reshaped on Korean forums in the 2010s','Use it in casual talk when experiences differ.',NULL,'{"Case by case",ke-ba-ke}'::text[],'[{"text": "How spicy it feels is sa-ba-sa.", "situation": "Talking about spicy food"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='d91d8458-f7e8-4577-ae36-ebc5325dcc28' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','so-hwak-haeng','So-hwak-haeng (소확행): Small but Certain Happiness','Short for "small but certain happiness"','Small, sure joys in daily life, like fresh bread or a tidy drawer. The phrase comes from a 1986 essay by Japanese novelist Haruki Murakami. In Korea it became a 2018 consumer trend keyword and was voted top buzzword of that year in one survey.','A 1986 Haruki Murakami phrase that became a 2018 Korean trend word','Use it to talk about small daily pleasures.',NULL,'{"Small happiness"}'::text[],'[{"text": "This is my so-hwak-haeng.", "situation": "A new ice cream on the way home"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='1efedfe1-62c5-4ea8-98aa-21855e45be1b' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','sonjeol','Sonjeol (손절): Cutting Someone Off','Ending a relationship with someone','Originally stock slang for selling at a loss to cut losses. People misread "son" as "hand", as in "cutting hands", so it came to mean cutting ties with a person. Entertainment news used it for brands dropping scandal-hit models.','Stock-market slang that took on a "cut ties" meaning in the mid-to-late 2010s','Use it to say you ended a bad relationship.','Telling others to cut off a real person can look like bullying.','{"Cut off","Cut ties"}'::text[],'[{"text": "At this point, sonjeol is fine.", "situation": "A friend keeps breaking promises"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='604094db-1433-4460-a26b-64df7b0f4c85' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','self-made-disaster','Seu-bul-jae (스불재): Self-Made Disaster','Short for "a disaster I brought on myself"','A wry way to say your own choice got you into trouble, like a delayed assignment, too many plans, or a late-night snack. It comes from a line in the 1997 rock song "Lazenca, Save Us" by N.EX.T.','A 1997 N.EX.T song lyric that spread as a karaoke-screen meme, then shortened to seu-bul-jae','Best for joking about yourself.','Can sound sarcastic about other people''s trouble.','{"Self-inflicted disaster"}'::text[],'[{"text": "This is a perfect seu-bul-jae.", "situation": "Pulling an all-nighter"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='4ac44118-2802-4a40-8cc6-d1f15a568122' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','slickback-challenge','Slickback Challenge (슬릭백)','A dance where you seem to glide sideways in the air','Fast foot moves make you look like you are sliding sideways. US TikToker jubi2fye started it in 2022 (also called the "Jubi Slide"). In Korea it boomed in 2023 when TikToker Lee Hyo-cheol posted clips that looked like floating. The name comes from the song "A Pimp Named SlickBack".','Started by jubi2fye in the US in 2022, huge in Korea in 2023','Use it with dance videos or when someone moves super fast.','Do not try it on slippery or narrow floors.','{"Jubi Slide",SlickBack}'::text[],'[{"text": "Can you do the slickback? Show me.", "situation": "Break time at school"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='7aefb4d6-1875-4fe0-a559-3506242535da' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','aboha','Aboha (아보하): A Very Ordinary Day','Short for "a very ordinary day", valuing a calm normal day','It praises a plain day where nothing bad happened. The book "Trend Korea 2025" named it a key trend. It shows a shift from pushing hard (god-saeng) to wanting a calm daily life.','Introduced as a "Trend Korea 2025" keyword in late 2024','Use it when talking about a calm daily life.',NULL,'{"Ordinary day"}'::text[],'[{"text": "Nothing happened today. A perfect aboha.", "situation": "Evening journal"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='e8a66b9e-19d7-4170-ac86-c9cfd0f1f5ae' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','ajae-gag','Ajae Gag (아재개그): Dad Jokes','Corny puns that make you groan and smile','Jokes an "ajae" (middle-aged man) might tell: unfunny puns that still get a little laugh, much like English "dad jokes". It continues the "sseolleong" (chilly) jokes of the 1990s. Now any corny pun counts, whatever the speaker''s age.','Follows 1990s "chilly jokes", named ajae gag on TV and online in the mid-2010s','Use it when you make or hear a corny pun.',NULL,'{"Dad joke","Corny joke"}'::text[],'[{"text": "Okay, that was an ajae gag.", "situation": "After your own pun"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='957f99d5-49e1-4174-b885-b10b1baf0804' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','al-jal-ttak-kkal-sen','Al-jal-ttak-kkal-sen (알잘딱깔센)','Short for "do it well, neatly, and with good sense, on your own"','You say it when you want someone to handle a task smartly without step-by-step instructions, or to praise someone who did.','Spread through Korean streaming and online communities in the early 2020s (first user unclear)','Use it for casual requests among friends or peers.','Can sound bossy toward seniors.','{"Do it smart"}'::text[],'[{"text": "Design? Just al-jal-ttak-kkal-sen it.", "situation": "Asking for slides"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='66e5a4a3-7eae-49b2-a907-d377c923143f' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','eoljuga-iced-americano','Eol-jug-a (얼죽아): Iced Americano Even If I Freeze','Short for "iced Americano, even if I freeze to death"','People who drink iced Americano even in the middle of winter. Iced Americano is the top-selling café drink in Korea, often shortened to "a-a". A Starbucks Korea survey found about 6 in 10 customers order iced drinks even in winter.','Spread in Korean café culture in the late 2010s','Use it to describe yourself or a friend who always orders iced drinks.',NULL,'{a-a,"Iced Americano lover"}'::text[],'[{"text": "I am eol-jug-a, so iced Americano again.", "situation": "At a café on a freezing day"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='81e19563-b4bf-4728-8b95-3fb549553348' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','eomchina','Eomchina (엄친아): Mom''s Friend''s Son','The "perfect" kid parents compare you to','From parents saying "Mom''s friend''s son got first place again." That son sounds perfect at everything, so the word now means anyone who excels at all things. A daughter is "eomchinttal". It spread online around 2005, helped by the webtoon "Golbang Hwansanggok".','Spread online around 2005, popularized by a Naver webtoon','Use it for someone who is good at everything.','Comparing real people can make them uncomfortable.','{"Perfect kid",eomchinttal}'::text[],'[{"text": "He is a total eomchina.", "situation": "Talking about a top student"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='6cb937dc-8378-45bd-b015-bf70aaef27ba' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','oh-un-wan','O-un-wan (오운완): Today''s Workout Done','Short for "today''s workout, complete", a workout hashtag','A tag people add when they post a photo after finishing their workout. If posted a day late, it becomes "eo-un-wan" (yesterday''s workout done). It is also used to tease posts that are mainly about showing off.','Spread on Instagram and Korean social media in the early 2020s','Use it after a workout or to cheer a friend who trains often.','Avoid commenting on other people''s bodies.','{#ohunwan,"Workout done"}'::text[],'[{"text": "Leg day done. O-un-wan!", "situation": "Leaving the gym"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='42dda0df-7912-49e9-b65b-4cfb7ec7b6a1' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','even-better','Ohiryeo Joa (오히려 좋아): Even Better','Calling a bad turn of events good on purpose','When things go wrong, you say "even better!" and laugh it off. It became a meme from game streamers who said it smugly when losing. Many link it to streamer Chimchakman, but it was used earlier. It is cheekier than "Lucky Vicky".','Mid-2010s Korean game streams, a widespread meme by about 2020','Use it to laugh off small mistakes or changed plans.','It can sound like teasing if someone is really upset.','{"Even better","All according to plan"}'::text[],'[{"text": "Ohiryeo joa. Movie night at home.", "situation": "Rain cancels outdoor plans"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='cb3f1951-667b-4a2c-843b-8238f7b573d0' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','inssa','Inssa (인싸): The Social Insider','Short for "insider", someone who fits in and is popular','A person who mixes well and stands out in a group. The opposite is "assa" (outsider). Coined around 2004, it took off in 2017. Trendy items are "inssa-tem". It is Konglish: the meaning differs from English "insider".','Used from around 2004, big on Korean social media from 2017','Use it to praise a sociable friend or talk about trendy items.','Calling someone "assa" can sound like exclusion.','{Insider,inssa-tem}'::text[],'[{"text": "You are such an inssa.", "situation": "A friend is popular at every party"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='9fedb5ff-c774-4e0e-a966-d0c830e013f8' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','jeomechu','Jeo-me-chu (저메추): Dinner Menu Suggestions?','Short for "recommend me a dinner menu"','Posted alone in a group chat or forum, it asks people to suggest what to eat tonight. For lunch it becomes "jeom-me-chu", for late-night snacks "ya-me-chu". A classic example of byeol-da-jul.','Late 2010s, from post titles on Korean online forums asking for menu ideas','Use it to ask friends what to eat.',NULL,'{"Dinner recs",jeom-me-chu}'::text[],'[{"text": "Jeo-me-chu please, something with soup.", "situation": "In a group chat"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='3aad488f-aca3-4047-bb74-e41759abbd0a' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','unbroken-will','Jung-kkeok-ma (중꺾마): What Matters Is an Unbroken Will','Short for "what matters is a heart that does not break"','It means not giving up matters more than the result. It started as the title a news outlet gave to an interview video with pro gamer Deft (DRX) after a loss at the 2022 League of Legends World Championship. Deft did not say the exact words himself. Weeks later, Korean footballers held a flag with the phrase after reaching the 2022 World Cup round of 16.','2022 LoL Worlds interview with Deft, then the 2022 Qatar World Cup','Use it to cheer someone on.',NULL,'{"Unbroken will","Never give up"}'::text[],'[{"text": "Score aside, jung-kkeok-ma. We push to the end.", "situation": "Night before an exam"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='bf3cdc61-3fc9-48a3-8957-9ccd43e3c28f' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','choeae','Choeae (최애): My Bias','Your favorite person, member or character','An old word for "most loved" that fan culture revived in the 2010s to mean your favorite member or character, like "bias" in English-speaking K-pop fandom. Your second favorite is "chaae". Now used for any favorite thing.','Anime fandom''s "choeae-kae" moved into K-pop fandom in the 2010s','Use it to name your favorite member, food or song.',NULL,'{Bias,Favorite}'::text[],'[{"text": "My choeae in this group is the youngest.", "situation": "Talking about a K-pop group"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='46fcc98e-36e8-4692-9408-3e0b0aa01922' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','chugu-mi','Chugu-mi (추구미): My Aesthetic Goal','The look or vibe you want to have','Short for "the beauty I pursue". It is the style, fashion, or mood you aim for. People share a celeb or character photo and say "This is my chugu-mi".','Started on Korean fashion and beauty social media around 2023, a top Gen Z word in 2024','Use it to talk about taste.',NULL,'{"My aesthetic","Goal vibe"}'::text[],'[{"text": "This mood is exactly my chugu-mi.", "situation": "Showing a photo"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='2d5669d4-62ff-40dc-af82-fd7d1fc3c304' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','form-is-crazy','Form Is Crazy (폼 미쳤다)','Praise for someone in amazing shape or skill lately','From the sports word "form", meaning an athlete''s condition. When someone is doing great lately, you say their form is crazy.','Sports fans'' comments on athlete videos, spread into daily talk around 2023','Use it to praise friends.','Contains "crazy", so skip it in formal settings.','{"On fire"}'::text[],'[{"text": "Your form is crazy lately.", "situation": "A friend wins three in a row"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='8b57da15-d644-423d-af1c-8af6cc780a12' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','fu-bao','Fu Bao (푸바오): Korea''s Beloved Panda','The first giant panda born naturally in Korea','Born in July 2020 at Everland in Yongin, Fu Bao was the first panda bred naturally in Korea. The name means "treasure that gives happiness". Videos with keeper Kang Cheol-won ("Kang Bao") made her hugely popular, and fans called her "Princess Fu". Her move to China in April 2024 drew big farewells.','Born at Everland in 2020, a national sensation through her April 2024 return to China','Use it when sharing panda videos or talking about Fu Bao.',NULL,'{"Princess Fu",Fubao}'::text[],'[{"text": "Fu Bao eating bamboo never gets old.", "situation": "Watching a panda video"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='95bdd0f8-e8fb-4de4-a445-9be6a1f4b414' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','heol','Heol (헐): OMG / Whoa','A short gasp of surprise or disbelief','Koreans say "heol" when they hear something hard to believe or see something absurd. It lingers longer than "heok" (gasp), so it became more popular. Almost every generation uses it now. Its origin is unclear; one likely theory points to old martial-arts novels.','Recorded before the 1990s with an unclear origin, widespread online in the 2000s','Use it to react to surprising news among friends.','Saying "heol" to a senior can sound rude.','{OMG,Whoa}'::text[],'[{"text": "Heol, really? When?", "situation": "Hearing surprising news"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='de3c03a2-e6d6-493a-97cd-fce8aa4843e7' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','honbap','Honbap (혼밥): Eating Alone','Eating a meal by yourself','Short for "honja bap" (eating alone). More people eat alone to choose their own food and pace, so the word spread. It started a pattern: "honsul" (drinking alone), "honyeong" (movies alone). Many restaurants now have seats for solo diners.','Spread in the mid-2010s as single-person households grew','Use it to say you are eating alone or to find solo-friendly places.',NULL,'{"Solo dining",honsul}'::text[],'[{"text": "I will do honbap today and rest a bit.", "situation": "At lunchtime"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='b7f8cddb-02ef-440d-88f8-912c92b7585d' on conflict (meme_id,locale) do nothing;
insert into meme_translations (meme_id,locale,localized_slug,title,summary,description,origin,usage_note,caution,aliases,usage_examples,status,source_updated_at,provider,model,prompt_version,reviewed_at,reviewed_by) select m.id,'en','heukyeoksa','Heukyeoksa (흑역사): Dark History','An embarrassing past you want to erase','Embarrassing things you said or did and would rather forget. It comes from the Japanese anime "Turn A Gundam", where "dark history" named a forgotten era. It caught on so widely that Japan added it to dictionaries, and Koreans of all ages use it too.','From the 1999 Japanese anime "Turn A Gundam", adopted into Korean slang','Use it to laugh about your own past.','Spreading someone else''s dark history can hurt.','{"Cringe past"}'::text[],'[{"text": "This photo is my heukyeoksa. Delete it.", "situation": "Seeing an old photo"}]'::jsonb,'reviewed',m.updated_at,'editorial','human',1,now(),(select id from profiles where role='operator' order by created_at limit 1) from memes m where m.id='d09e6f38-f918-4c85-b6f9-6a9efb2d5f24' on conflict (meme_id,locale) do nothing;
